const t=(title,body,formula)=>({title,body:'<p>'+body+'</p>',formula});
function insertTopic(chapter,topic,before){
 topic.anchor='topic-'+chapter.theory.length;
 const index=before?chapter.theory.findIndex(t=>t.title===before):chapter.theory.length;
 if(index<0)throw new Error('Missing topic '+before);
 chapter.theory.splice(index,0,topic);
}
function moveTopic(chapter,title,before){
 const from=chapter.theory.findIndex(t=>t.title===title);
 if(from<0)throw new Error('Missing topic '+title);
 const [topic]=chapter.theory.splice(from,1);
 const to=chapter.theory.findIndex(t=>t.title===before);
 if(to<0)throw new Error('Missing topic '+before);
 chapter.theory.splice(to,0,topic);
}
